package ca.brtalgo.uberwatcher;
import android.Manifest;import android.app.Activity;import android.content.Intent;import android.content.pm.PackageManager;import android.os.Build;import android.os.Bundle;import android.provider.Settings;import android.widget.*;
public class MainActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);AlertHelper.createChannel(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},100);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(40,40,40,40);TextView t=new TextView(this);t.setText("Uber Opportunity Watcher");t.setTextSize(24);r.addView(t);TextView i=new TextView(this);i.setText("Enable Accessibility and Notification access. Keep Uber Driver visible for automatic refresh. Background monitoring can only use Uber notifications.");i.setTextSize(16);r.addView(i);Button a=new Button(this);a.setText("Enable Accessibility service");a.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));r.addView(a);Button n=new Button(this);n.setText("Enable Notification access");n.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)));r.addView(n);Button x=new Button(this);x.setText("Test alert");x.setOnClickListener(v->AlertHelper.notify(this,"TEST: Uber opportunity watcher","Alerts are working."));r.addView(x);Button u=new Button(this);u.setText("Open Uber Driver");u.setOnClickListener(v->{Intent q=getPackageManager().getLaunchIntentForPackage("com.ubercab.driver");if(q!=null)startActivity(q);});r.addView(u);setContentView(r);}}
